Framework: common
Heading: Use a Reduced Spring Application Context
Document Path: v25.3/building-apps/testing/browserless/speed-up-tests.md (use get_full_document to get complete context)
----

```java
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.test.context.ContextConfiguration;
import com.vaadin.browserless.SpringBrowserlessTest;
import com.vaadin.browserless.ViewPackages;
import com.vaadin.flow.component.notification.Notification;

@ViewPackages(classes = ServiceGreetingView.class)
@ContextConfiguration(classes = GreetingTestConfig.class)
class ServiceGreetingViewTest extends SpringBrowserlessTest {
    @Test
    void greeting_usesTestService() {
        var view = navigate(ServiceGreetingView.class);
        test(view.name).setValue("Test");
        test(view.sayHello).click();
        Notification notification = find(Notification.class).single();
        Assertions.assertEquals("Hello Test", test(notification).getText());
    }
}

@TestConfiguration
class GreetingTestConfig {
    @Bean
    GreetingService greetingService() {
        return name -> "Hello " + name;
    }
}
```

Annotate the configuration with `@TestConfiguration` rather than `@Configuration`.
Spring Boot's component scan skips test configuration classes, so the test service doesn't also end up in the `@SpringBootTest` contexts of other tests in the same package, where it would conflict with the application's service.

